class Solution {
  public long minIncrementOperations(int[] nums, int k) {
    // cost[i]: raise nums[i] to k; dp[i]: cheapest plan whose latest big element is i
    long previous1 = 0, previous2 = 0, previous3 = 0;
    for (int x : nums) {
      long current = Math.max(0, k - x) + Math.min(previous1, Math.min(previous2, previous3));
      previous3 = previous2;
      previous2 = previous1;
      previous1 = current;
    }
    return Math.min(previous1, Math.min(previous2, previous3));
  }
}
